INSERT INTO landing_pages (slug, label, is_published, cta_region_slug, image_url, image_alt, sort_order, h1_en, intro_en, content_en, meta_title_en, meta_description_en, h1_tr, intro_tr, content_tr, meta_title_tr, meta_description_tr, h1_de, intro_de, content_de, meta_title_de, meta_description_de, h1_pl, intro_pl, content_pl, meta_title_pl, meta_description_pl, h1_ru, intro_ru, content_ru, meta_title_ru, meta_description_ru, h1_nl, intro_nl, content_nl, meta_title_nl, meta_description_nl, h1_ro, intro_ro, content_ro, meta_title_ro, meta_description_ro)
SELECT 'hotel-transfer-antalya', 'Hotel Transfer Antalya', true, NULL, 'C:/Program Files/Git/images/antalya-airport.jpg', 'Antalya Airport hotel transfer to any resort', 103, 'Hotel Transfer Antalya Airport', 'One booking, any hotel on the Turkish Riviera — you just need the hotel name, we handle the route.', '<p>Most transfer sites make you pick a resort area before they''ll quote you a price. We don''t. Tell us your hotel name when you book, and we route the driver there directly — whether it''s a five-star resort in Belek or a small boutique hotel in a street your map app has never heard of. The driver already has the exact address before you land.</p><p>Arriving after midnight? Your driver is already scheduled — no extra fee, no need to call ahead.</p><h2>Why This Is Different From a Regular Airport Transfer</h2><ul><li>Works for any named hotel, not just the big resort brands</li><li>Driver has your exact hotel address before your flight lands</li><li>No need to know your "resort area" — just your hotel name</li><li>Fixed price quoted at booking, based on real distance to your hotel</li><li>Late check-in? Driver waits — no extra charge for night arrivals</li><li>One transfer per hotel booking, even for groups arriving on different flights</li><li>Return transfer from the same hotel bookable in one go</li><li>Covers every hotel from Kundu-Lara to Alanya, door to door</li></ul><h2>A Few Hotels We Transfer To Every Week</h2><ul><li>Titanic Deluxe Lara</li><li>Rixos Premium Belek</li><li>Maxx Royal Belek</li><li>Regnum Carya</li><li>Rixos Premium Tekirova</li><li>Delphin Imperial</li><li>Royal Seginus</li><li>Granada Luxury Okurcalar</li></ul><h2>Or Browse by Resort Area</h2><ul><li><a href="/belek-transfer">Hotels in Belek</a></li><li><a href="/side-transfer">Hotels in Side</a></li><li><a href="/alanya-transfer">Hotels in Alanya</a></li><li><a href="/kemer-transfer">Hotels in Kemer</a></li><li><a href="/kundu-lara-transfer">Hotels in Kundu-Lara</a></li><li><a href="/sehirici-transfer">Hotels in Antalya City</a></li></ul><h2>Frequently Asked Questions</h2><h3>Do you transfer to my exact hotel even if it''s not a big resort brand?</h3><p>Yes. Enter your hotel''s name and address when booking and the driver is routed there directly — we''re not limited to a fixed list of partner hotels. Small boutique hotels and apartments are just as easy to reach as five-star resorts.</p><h3>What if I don''t know which resort area my hotel is in?</h3><p>You don''t need to. Type your hotel name in the booking form — the system looks up the location itself, so you never have to identify Belek, Side, or any other area yourself.</p><h3>How does the driver find my hotel at night?</h3><p>Every driver receives your hotel''s GPS coordinates before pickup, not just a name. Night arrivals cost the same as day arrivals — there''s no late-arrival surcharge.</p><h3>Is the price different depending on which hotel I choose?</h3><p>Yes, honestly — price is based on the real driving distance to your hotel, shown to you before you confirm, never a flat guess. Two hotels in the same town can have slightly different prices if one is further off the main road.</p><h3>Can I book a hotel transfer for a group arriving on separate flights?</h3><p>Yes. Add each flight''s arrival time in the booking notes and we''ll schedule separate pickups to the same hotel, or combine them into one vehicle if the timing allows.</p>', 'Hotel Transfer Antalya Airport | Direct to Any Hotel, Any Resort', 'Hotel transfer from Antalya Airport to any hotel on the coast — you don''t need to know your exact resort area to book. Fixed price, driver knows the address. Book online.', 'Antalya Havalimanı Otel Transferi', 'Tek rezervasyon, Türk Rivierası''ndaki her otel — sadece otel adını yazın, rotayı biz hallederiz.', '<p>Çoğu transfer sitesi fiyat vermeden önce bir tatil bölgesi seçmenizi ister. Biz istemeyiz. Rezervasyon yaparken otel adınızı yazın, şoförü doğrudan oraya yönlendiririz — ister Belek''te beş yıldızlı bir tesis olsun, ister harita uygulamanızın bile duymadığı bir sokaktaki küçük butik otel. Şoförünüzde siz inmeden önce tam adres hazır olur.</p><p>Gece yarısından sonra mı varıyorsunuz? Şoförünüz zaten planlanmış — ek ücret yok, önceden aramanıza gerek yok.</p><h2>Bu Neden Sıradan Bir Havalimanı Transferinden Farklı</h2><ul><li>Sadece büyük otel zincirleri için değil, ismi girilen her otel için çalışır</li><li>Şoförde uçuşunuz inmeden önce tam otel adresiniz hazır olur</li><li>"Bölgenizi" bilmenize gerek yok — sadece otel adınız yeterli</li><li>Rezervasyonda otelinize gerçek mesafeye göre sabit fiyat verilir</li><li>Geç check-in mi? Şoför bekler — gece varışlarında ek ücret yok</li><li>Farklı uçuşlarla gelen gruplar için otel başına tek rezervasyon</li><li>Aynı otelden dönüş transferi tek seferde rezerve edilebilir</li><li>Kundu-Lara''dan Alanya''ya kadar her oteli kapıdan kapıya kapsar</li></ul><h2>Her Hafta Transfer Yaptığımız Bazı Oteller</h2><ul><li>Titanic Deluxe Lara</li><li>Rixos Premium Belek</li><li>Maxx Royal Belek</li><li>Regnum Carya</li><li>Rixos Premium Tekirova</li><li>Delphin Imperial</li><li>Royal Seginus</li><li>Granada Luxury Okurcalar</li></ul><h2>Veya Tatil Bölgesine Göre İnceleyin</h2><ul><li><a href="/belek-transfer">Belek''teki Oteller</a></li><li><a href="/side-transfer">Side''deki Oteller</a></li><li><a href="/alanya-transfer">Alanya''daki Oteller</a></li><li><a href="/kemer-transfer">Kemer''deki Oteller</a></li><li><a href="/kundu-lara-transfer">Kundu-Lara''daki Oteller</a></li><li><a href="/sehirici-transfer">Antalya Şehir Merkezi Otelleri</a></li></ul><h2>Sık Sorulan Sorular</h2><h3>Büyük bir otel zinciri olmasa bile tam olarak benim otelime transfer yapıyor musunuz?</h3><p>Evet. Rezervasyon sırasında otelinizin adını ve adresini girin, şoför doğrudan oraya yönlendirilir — sabit bir partner otel listesiyle sınırlı değiliz. Küçük butik oteller ve apartlar da beş yıldızlı tesisler kadar kolay ulaşılabilir.</p><h3>Otelimin hangi tatil bölgesinde olduğunu bilmiyorsam ne olur?</h3><p>Bilmenize gerek yok. Rezervasyon formuna otel adınızı yazın — sistem konumu kendisi bulur, Belek, Side veya başka bir bölgeyi kendiniz belirlemeniz gerekmez.</p><h3>Şoför gece otelimi nasıl buluyor?</h3><p>Her şoför, karşılamadan önce sadece isim değil, otelinizin GPS konumunu da alır. Gece varışları gündüz varışlarıyla aynı fiyattır — geç varış için ek ücret yoktur.</p><h3>Hangi oteli seçtiğime göre fiyat değişiyor mu?</h3><p>Evet, dürüst olmak gerekirse — fiyat otelinize olan gerçek sürüş mesafesine göre belirlenir ve onaylamadan önce size gösterilir, asla düz bir tahmin değildir. Aynı şehirdeki iki otel, biri ana yoldan uzaksa hafif farklı fiyatlara sahip olabilir.</p><h3>Farklı uçuşlarla gelen bir grup için otel transferi rezerve edebilir miyim?</h3><p>Evet. Her uçuşun varış saatini rezervasyon notlarına ekleyin; aynı otele ayrı karşılamalar planlarız ya da zamanlama uygunsa tek araçta birleştiririz.</p>', 'Antalya Havalimanı Otel Transferi | Her Otele, Her Bölgeye Direkt', 'Antalya Havalimanı''ndan sahildeki her otele transfer — rezervasyon için hangi bölgede olduğunuzu bilmenize gerek yok. Sabit fiyat, şoför adresi biliyor. Online rezervasyon.', 'Hotel Transfer Antalya Flughafen', 'Eine Buchung, jedes Hotel an der Türkischen Riviera — Sie brauchen nur den Hotelnamen, die Route übernehmen wir.', '<p>Die meisten Transferseiten verlangen, dass Sie zuerst ein Ferienort auswählen, bevor sie Ihnen einen Preis nennen. Wir nicht. Geben Sie beim Buchen einfach Ihren Hotelnamen an, und wir leiten den Fahrer direkt dorthin — egal ob es ein Fünf-Sterne-Resort in Belek oder ein kleines Boutique-Hotel in einer Straße ist, von der Ihre Karten-App noch nie gehört hat. Der Fahrer hat die genaue Adresse, bevor Sie landen.</p><p>Ankunft nach Mitternacht? Ihr Fahrer ist bereits eingeplant — keine Zusatzkosten, kein Anruf vorab nötig.</p><h2>Warum Das Anders Ist Als Ein Normaler Flughafentransfer</h2><ul><li>Funktioniert für jedes benannte Hotel, nicht nur große Ferienort-Marken</li><li>Fahrer hat Ihre genaue Hoteladresse, bevor Ihr Flug landet</li><li>Sie müssen Ihr "Ferienort" nicht kennen — nur Ihren Hotelnamen</li><li>Festpreis bei der Buchung, basierend auf der tatsächlichen Entfernung zu Ihrem Hotel</li><li>Später Check-in? Der Fahrer wartet — keine Zusatzkosten bei nächtlicher Ankunft</li><li>Ein Transfer pro Hotelbuchung, auch bei Gruppen mit unterschiedlichen Flügen</li><li>Rücktransfer vom selben Hotel in einem Schritt buchbar</li><li>Deckt jedes Hotel von Kundu-Lara bis Alanya ab, Tür zu Tür</li></ul><h2>Einige Hotels, Zu Denen Wir Jede Woche Fahren</h2><ul><li>Titanic Deluxe Lara</li><li>Rixos Premium Belek</li><li>Maxx Royal Belek</li><li>Regnum Carya</li><li>Rixos Premium Tekirova</li><li>Delphin Imperial</li><li>Royal Seginus</li><li>Granada Luxury Okurcalar</li></ul><h2>Oder Nach Ferienort Durchsuchen</h2><ul><li><a href="/belek-transfer">Hotels in Belek</a></li><li><a href="/side-transfer">Hotels in Side</a></li><li><a href="/alanya-transfer">Hotels in Alanya</a></li><li><a href="/kemer-transfer">Hotels in Kemer</a></li><li><a href="/kundu-lara-transfer">Hotels in Kundu-Lara</a></li><li><a href="/sehirici-transfer">Hotels in Antalya Stadt</a></li></ul><h2>Häufig gestellte Fragen</h2><h3>Fahren Sie auch zu meinem Hotel, wenn es keine große Ferienort-Marke ist?</h3><p>Ja. Geben Sie beim Buchen Name und Adresse Ihres Hotels an, und der Fahrer wird direkt dorthin geleitet — wir sind nicht auf eine feste Liste von Partnerhotels beschränkt. Kleine Boutique-Hotels und Apartments sind genauso leicht zu erreichen wie Fünf-Sterne-Resorts.</p><h3>Was, wenn ich nicht weiß, in welchem Ferienort mein Hotel liegt?</h3><p>Das müssen Sie nicht wissen. Geben Sie einfach Ihren Hotelnamen im Buchungsformular ein — das System findet den Standort selbst, Sie müssen Belek, Side oder ein anderes Gebiet nicht selbst bestimmen.</p><h3>Wie findet der Fahrer mein Hotel nachts?</h3><p>Jeder Fahrer erhält vor der Abholung die GPS-Koordinaten Ihres Hotels, nicht nur den Namen. Nächtliche Ankünfte kosten genauso viel wie tagsüber — es gibt keinen Nachtzuschlag.</p><h3>Ist der Preis je nach gewähltem Hotel unterschiedlich?</h3><p>Ja, ehrlich gesagt — der Preis basiert auf der tatsächlichen Fahrstrecke zu Ihrem Hotel und wird Ihnen vor der Bestätigung angezeigt, nie eine pauschale Schätzung. Zwei Hotels in derselben Stadt können leicht unterschiedliche Preise haben, wenn eines weiter von der Hauptstraße entfernt liegt.</p><h3>Kann ich einen Hoteltransfer für eine Gruppe mit getrennten Flügen buchen?</h3><p>Ja. Geben Sie die Ankunftszeit jedes Fluges in den Buchungshinweisen an, und wir planen getrennte Abholungen zum selben Hotel oder kombinieren sie in einem Fahrzeug, wenn die Zeiten es zulassen.</p>', 'Hotel Transfer Antalya Flughafen | Direkt zu Jedem Hotel, Jedem Ort', 'Hotel Transfer vom Flughafen Antalya zu jedem Hotel an der Küste — Sie müssen Ihr genaues Ferienort nicht kennen, um zu buchen. Festpreis, Fahrer kennt die Adresse. Online buchen.', 'Transfer do Hotelu Antalya Lotnisko', 'Jedna rezerwacja, każdy hotel na Riwierze Tureckiej — wystarczy nazwa hotelu, trasę ustalamy my.', '<p>Większość stron z transferami wymaga wyboru kurortu, zanim poda Ci cenę. My nie. Podaj nazwę hotelu podczas rezerwacji, a my skierujemy kierowcę bezpośrednio tam — niezależnie czy to pięciogwiazdkowy resort w Belek, czy mały butikowy hotel przy ulicy, o której Twoja mapa nigdy nie słyszała. Kierowca ma dokładny adres, zanim wylądujesz.</p><p>Przylatujesz po północy? Twój kierowca jest już zaplanowany — bez dodatkowej opłaty, bez konieczności dzwonienia wcześniej.</p><h2>Dlaczego To Się Różni Od Zwykłego Transferu z Lotniska</h2><ul><li>Działa dla każdego nazwanego hotelu, nie tylko dużych marek kurortowych</li><li>Kierowca ma Twój dokładny adres hotelu przed lądowaniem samolotu</li><li>Nie musisz znać swojego "kurortu" — wystarczy nazwa hotelu</li><li>Stała cena podana przy rezerwacji, oparta na rzeczywistej odległości do hotelu</li><li>Późne zameldowanie? Kierowca czeka — bez dopłaty za nocne przyloty</li><li>Jeden transfer na rezerwację hotelu, nawet dla grup przylatujących różnymi lotami</li><li>Transfer powrotny z tego samego hotelu można zarezerwować od razu</li><li>Obejmuje każdy hotel od Kundu-Lara po Alanyę, od drzwi do drzwi</li></ul><h2>Kilka Hoteli, Do Których Jeździmy Co Tydzień</h2><ul><li>Titanic Deluxe Lara</li><li>Rixos Premium Belek</li><li>Maxx Royal Belek</li><li>Regnum Carya</li><li>Rixos Premium Tekirova</li><li>Delphin Imperial</li><li>Royal Seginus</li><li>Granada Luxury Okurcalar</li></ul><h2>Lub Przeglądaj Według Kurortu</h2><ul><li><a href="/belek-transfer">Hotele w Belek</a></li><li><a href="/side-transfer">Hotele w Side</a></li><li><a href="/alanya-transfer">Hotele w Alanyi</a></li><li><a href="/kemer-transfer">Hotele w Kemer</a></li><li><a href="/kundu-lara-transfer">Hotele w Kundu-Lara</a></li><li><a href="/sehirici-transfer">Hotele w Centrum Antalyi</a></li></ul><h2>Najczęściej zadawane pytania</h2><h3>Czy dojedziecie do mojego hotelu, nawet jeśli to nie duża marka kurortowa?</h3><p>Tak. Podaj nazwę i adres swojego hotelu podczas rezerwacji, a kierowca zostanie skierowany bezpośrednio tam — nie jesteśmy ograniczeni do stałej listy hoteli partnerskich. Małe hotele butikowe i apartamenty są równie łatwo dostępne jak pięciogwiazdkowe resorty.</p><h3>Co, jeśli nie wiem, w którym kurorcie znajduje się mój hotel?</h3><p>Nie musisz tego wiedzieć. Wpisz nazwę hotelu w formularzu rezerwacji — system sam znajdzie lokalizację, nie musisz samodzielnie określać, czy to Belek, Side czy inny obszar.</p><h3>Jak kierowca znajduje mój hotel w nocy?</h3><p>Każdy kierowca otrzymuje współrzędne GPS Twojego hotelu przed odbiorem, nie tylko nazwę. Przyloty nocne kosztują tyle samo co dzienne — nie ma dopłaty za późny przylot.</p><h3>Czy cena różni się w zależności od wybranego hotelu?</h3><p>Tak, szczerze mówiąc — cena opiera się na rzeczywistej odległości do Twojego hotelu i jest pokazywana przed potwierdzeniem, nigdy nie jest płaskim szacunkiem. Dwa hotele w tym samym mieście mogą mieć nieco inne ceny, jeśli jeden znajduje się dalej od głównej drogi.</p><h3>Czy mogę zarezerwować transfer do hotelu dla grupy przylatującej różnymi lotami?</h3><p>Tak. Dodaj godzinę przylotu każdego lotu w uwagach do rezerwacji, a my zaplanujemy oddzielne odbiory do tego samego hotelu lub połączymy je w jednym pojeździe, jeśli czas na to pozwoli.</p>', 'Transfer do Hotelu Antalya Lotnisko | Bezpośrednio do Każdego Hotelu', 'Transfer do hotelu z lotniska Antalya do dowolnego hotelu na wybrzeżu — nie musisz znać nazwy swojego kurortu, by zarezerwować. Stała cena, kierowca zna adres. Rezerwacja online.', 'Трансфер в Отель из Аэропорта Анталии', 'Одно бронирование, любой отель на Турецкой Ривьере — нужно лишь название отеля, маршрут берём на себя мы.', '<p>Большинство сайтов трансферов просят сначала выбрать курортный район, прежде чем назвать цену. Мы — нет. Укажите название вашего отеля при бронировании, и мы направим водителя прямо туда — будь то пятизвёздочный курорт в Белеке или небольшой бутик-отель на улице, о которой ваше картографическое приложение никогда не слышало. У водителя уже есть точный адрес до вашей посадки.</p><p>Прибываете после полуночи? Ваш водитель уже запланирован — без доплаты, без необходимости звонить заранее.</p><h2>Чем Это Отличается от Обычного Трансфера из Аэропорта</h2><ul><li>Работает для любого названного отеля, а не только крупных курортных брендов</li><li>У водителя есть точный адрес вашего отеля ещё до посадки самолёта</li><li>Не нужно знать свой «курортный район» — достаточно названия отеля</li><li>Фиксированная цена при бронировании, рассчитанная по реальному расстоянию до отеля</li><li>Поздний заезд? Водитель ждёт — без доплаты за ночное прибытие</li><li>Один трансфер на бронирование отеля, даже для групп, прилетающих разными рейсами</li><li>Обратный трансфер из того же отеля можно забронировать сразу</li><li>Покрывает каждый отель от Кунду-Лары до Аланьи, от двери до двери</li></ul><h2>Несколько Отелей, Куда Мы Возим Каждую Неделю</h2><ul><li>Titanic Deluxe Lara</li><li>Rixos Premium Belek</li><li>Maxx Royal Belek</li><li>Regnum Carya</li><li>Rixos Premium Tekirova</li><li>Delphin Imperial</li><li>Royal Seginus</li><li>Granada Luxury Okurcalar</li></ul><h2>Или Выберите по Курортному Району</h2><ul><li><a href="/belek-transfer">Отели в Белеке</a></li><li><a href="/side-transfer">Отели в Сиде</a></li><li><a href="/alanya-transfer">Отели в Аланье</a></li><li><a href="/kemer-transfer">Отели в Кемере</a></li><li><a href="/kundu-lara-transfer">Отели в Кунду-Ларе</a></li><li><a href="/sehirici-transfer">Отели в центре Анталии</a></li></ul><h2>Часто задаваемые вопросы</h2><h3>Вы везёте к моему конкретному отелю, даже если это не крупный курортный бренд?</h3><p>Да. Укажите название и адрес отеля при бронировании, и водитель направляется прямо туда — мы не ограничены фиксированным списком отелей-партнёров. До небольших бутик-отелей и апартаментов добраться так же легко, как до пятизвёздочных курортов.</p><h3>Что делать, если я не знаю, в каком курортном районе находится мой отель?</h3><p>Вам не нужно это знать. Просто введите название отеля в форме бронирования — система сама определит местоположение, вам не нужно самостоятельно указывать Белек, Сиде или другой район.</p><h3>Как водитель находит мой отель ночью?</h3><p>Каждый водитель получает GPS-координаты вашего отеля перед встречей, а не только название. Ночные прибытия стоят так же, как и дневные — доплаты за поздний приезд нет.</p><h3>Отличается ли цена в зависимости от выбранного отеля?</h3><p>Да, честно говоря — цена основана на реальном расстоянии до вашего отеля и показывается вам перед подтверждением, а не является усреднённой оценкой. Два отеля в одном городе могут иметь немного разную цену, если один расположен дальше от главной дороги.</p><h3>Могу ли я забронировать трансфер в отель для группы, прилетающей разными рейсами?</h3><p>Да. Укажите время прибытия каждого рейса в примечаниях к бронированию, и мы организуем отдельные встречи в том же отеле или объединим их в одном автомобиле, если позволяет расписание.</p>', 'Трансфер в Отель из Аэропорта Анталии | Прямо к Любому Отелю', 'Трансфер в отель из аэропорта Анталии в любой отель на побережье — не нужно знать точный курортный район, чтобы забронировать. Фиксированная цена, водитель знает адрес. Онлайн-бронирование.', 'Hotel Transfer Antalya Luchthaven', 'Eén boeking, elk hotel aan de Turkse Rivièra — u hoeft alleen de hotelnaam te weten, wij regelen de route.', '<p>De meeste transferwebsites laten u eerst een resortgebied kiezen voordat ze een prijs geven. Wij niet. Vermeld uw hotelnaam bij het boeken, en wij sturen de chauffeur er rechtstreeks naartoe — of het nu een vijfsterrenresort in Belek is of een klein boetiekhotel in een straat waar uw kaarten-app nog nooit van heeft gehoord. De chauffeur heeft het exacte adres al voordat u landt.</p><p>Aankomst na middernacht? Uw chauffeur staat al ingepland — geen extra kosten, geen noodzaak om vooraf te bellen.</p><h2>Waarom Dit Anders Is Dan Een Gewone Luchthaventransfer</h2><ul><li>Werkt voor elk genoemd hotel, niet alleen grote resortmerken</li><li>Chauffeur heeft uw exacte hoteladres voordat uw vlucht landt</li><li>U hoeft uw "resortgebied" niet te kennen — alleen uw hotelnaam</li><li>Vaste prijs bij boeking, gebaseerd op de werkelijke afstand tot uw hotel</li><li>Laat inchecken? De chauffeur wacht — geen extra kosten bij nachtelijke aankomst</li><li>Eén transfer per hotelboeking, ook voor groepen die met verschillende vluchten aankomen</li><li>Retourtransfer vanaf hetzelfde hotel in één keer boekbaar</li><li>Dekt elk hotel van Kundu-Lara tot Alanya, van deur tot deur</li></ul><h2>Enkele Hotels Waar Wij Elke Week Naartoe Rijden</h2><ul><li>Titanic Deluxe Lara</li><li>Rixos Premium Belek</li><li>Maxx Royal Belek</li><li>Regnum Carya</li><li>Rixos Premium Tekirova</li><li>Delphin Imperial</li><li>Royal Seginus</li><li>Granada Luxury Okurcalar</li></ul><h2>Of Bekijk Per Resortgebied</h2><ul><li><a href="/belek-transfer">Hotels in Belek</a></li><li><a href="/side-transfer">Hotels in Side</a></li><li><a href="/alanya-transfer">Hotels in Alanya</a></li><li><a href="/kemer-transfer">Hotels in Kemer</a></li><li><a href="/kundu-lara-transfer">Hotels in Kundu-Lara</a></li><li><a href="/sehirici-transfer">Hotels in Antalya centrum</a></li></ul><h2>Veelgestelde vragen</h2><h3>Rijdt u ook naar mijn specifieke hotel als het geen groot resortmerk is?</h3><p>Ja. Vul de naam en het adres van uw hotel in bij het boeken, en de chauffeur wordt er rechtstreeks naartoe geleid — wij zijn niet beperkt tot een vaste lijst van partnerhotels. Kleine boetiekhotels en appartementen zijn net zo makkelijk te bereiken als vijfsterrenresorts.</p><h3>Wat als ik niet weet in welk resortgebied mijn hotel ligt?</h3><p>Dat hoeft u niet te weten. Typ uw hotelnaam in het boekingsformulier — het systeem zoekt de locatie zelf op, u hoeft Belek, Side of een ander gebied niet zelf te bepalen.</p><h3>Hoe vindt de chauffeur mijn hotel ''s nachts?</h3><p>Elke chauffeur ontvangt de GPS-coördinaten van uw hotel vóór het ophalen, niet alleen de naam. Nachtelijke aankomsten kosten hetzelfde als aankomsten overdag — er is geen nachttoeslag.</p><h3>Verschilt de prijs afhankelijk van welk hotel ik kies?</h3><p>Ja, eerlijk gezegd — de prijs is gebaseerd op de werkelijke rijafstand tot uw hotel en wordt u getoond voordat u bevestigt, nooit een vaste schatting. Twee hotels in dezelfde stad kunnen licht verschillende prijzen hebben als het ene verder van de hoofdweg ligt.</p><h3>Kan ik een hoteltransfer boeken voor een groep die met verschillende vluchten aankomt?</h3><p>Ja. Voeg de aankomsttijd van elke vlucht toe in de boekingsnotities, en wij plannen aparte ophaalmomenten naar hetzelfde hotel, of combineren ze in één voertuig als de timing het toelaat.</p>', 'Hotel Transfer Antalya Luchthaven | Direct naar Elk Hotel, Elke Regio', 'Hoteltransfer van de luchthaven Antalya naar elk hotel aan de kust — u hoeft uw exacte resortgebied niet te kennen om te boeken. Vaste prijs, chauffeur kent het adres. Boek online.', 'Transfer hotel Aeroportul Antalya', 'O singură rezervare, orice hotel de pe Riviera Turcească — tu trebuie să știi doar numele hotelului, de rută ne ocupăm noi.', '<p>Majoritatea site-urilor de transfer îți cer să alegi mai întâi o zonă de stațiune înainte să îți dea un preț. Noi nu. Scrie numele hotelului la rezervare și trimitem șoferul direct acolo — fie că este un resort de cinci stele din Belek, fie un mic hotel boutique de pe o stradă despre care aplicația ta de hărți nu a auzit niciodată. Șoferul are adresa exactă înainte ca tu să aterizezi.</p><p>Ajungi după miezul nopții? Șoferul este deja programat — fără costuri suplimentare și fără să fie nevoie să suni dinainte.</p><h2>De ce este altfel decât un transfer obișnuit de aeroport</h2><ul><li>Funcționează pentru orice hotel cu nume, nu doar pentru marile lanțuri de resorturi</li><li>Șoferul are adresa exactă a hotelului tău înainte ca avionul să aterizeze</li><li>Nu trebuie să știi „zona de stațiune” — doar numele hotelului</li><li>Preț fix la rezervare, calculat pe distanța reală până la hotelul tău</li><li>Check-in târziu? Șoferul așteaptă — fără costuri suplimentare pentru sosirile de noapte</li><li>Un transfer per rezervare de hotel, inclusiv pentru grupuri care sosesc cu zboruri diferite</li><li>Cursa de retur de la același hotel se rezervă odată cu prima</li><li>Acoperă orice hotel de la Kundu-Lara până la Alanya, din ușă în ușă</li></ul><h2>Câteva hoteluri către care mergem în fiecare săptămână</h2><ul><li>Titanic Deluxe Lara</li><li>Rixos Premium Belek</li><li>Maxx Royal Belek</li><li>Regnum Carya</li><li>Rixos Premium Tekirova</li><li>Delphin Imperial</li><li>Royal Seginus</li><li>Granada Luxury Okurcalar</li></ul><h2>Sau caută după zona de stațiune</h2><ul><li><a href="/belek-transfer">Hoteluri în Belek</a></li><li><a href="/side-transfer">Hoteluri în Side</a></li><li><a href="/alanya-transfer">Hoteluri în Alanya</a></li><li><a href="/kemer-transfer">Hoteluri în Kemer</a></li><li><a href="/kundu-lara-transfer">Hoteluri în Kundu-Lara</a></li><li><a href="/sehirici-transfer">Hoteluri în centrul Antalyei</a></li></ul><h2>Întrebări frecvente</h2><h3>Mergeți și la hotelul meu dacă nu este un lanț mare de resorturi?</h3><p>Da. Scrie numele și adresa hotelului la rezervare, iar șoferul este îndrumat direct acolo — nu suntem limitați la o listă fixă de hoteluri partenere. Hotelurile boutique mici și apartamentele sunt la fel de ușor de găsit ca resorturile de cinci stele.</p><h3>Ce fac dacă nu știu în ce zonă de stațiune se află hotelul meu?</h3><p>Nu trebuie să știi. Scrie numele hotelului în formularul de rezervare — sistemul îi găsește singur locația, nu trebuie să decizi tu dacă este Belek, Side sau altă zonă.</p><h3>Cum găsește șoferul hotelul meu noaptea?</h3><p>Fiecare șofer primește coordonatele GPS ale hotelului înainte de preluare, nu doar numele. Sosirile de noapte costă la fel ca cele de zi — nu există taxă de noapte.</p><h3>Prețul diferă în funcție de hotelul ales?</h3><p>Da, sincer — prețul se calculează pe distanța reală de condus până la hotelul tău și îți este arătat înainte de confirmare, niciodată ca o estimare fixă. Două hoteluri din același oraș pot avea prețuri ușor diferite dacă unul este mai departe de drumul principal.</p><h3>Pot rezerva un transfer pentru un grup care sosește cu zboruri diferite?</h3><p>Da. Adaugă ora de sosire a fiecărui zbor în observațiile rezervării, iar noi programăm preluări separate către același hotel sau le combinăm într-un singur vehicul, dacă orele permit.</p>', 'Transfer hotel Aeroportul Antalya | Direct la orice hotel, în orice regiune', 'Transfer de la Aeroportul Antalya la orice hotel de pe coastă — nu trebuie să știi zona exactă a stațiunii ca să rezervi. Preț fix, șoferul cunoaște adresa. Rezervă online.'
WHERE NOT EXISTS (SELECT 1 FROM landing_pages WHERE slug = 'hotel-transfer-antalya');
